# T5: Ledger keeps an audit history

Give stocklib.ledger.Ledger an audit trail: Ledger.history() returns a list of (operation, sku, qty) tuples, operation 'add' or 'remove', in call order, recording only operations that succeeded (a call that raises is not recorded). history() returns a copy, so mutating the returned list does not change the ledger.
------
diff --git a/stocklib/ledger.py b/stocklib/ledger.py
index 31adec4..4b567be 100644
--- a/stocklib/ledger.py
+++ b/stocklib/ledger.py
@@ -4,11 +4,13 @@
 class Ledger:
     def __init__(self):
         self._stock = {}
+        self._history = []

     def add(self, sku, qty):
         if qty <= 0:
             raise ValueError("qty to add must be positive")
         self._stock[sku] = self._stock.get(sku, 0) + qty
+        self._history.append(("add", sku, qty))

     def remove(self, sku, qty):
         if qty <= 0:
@@ -16,9 +18,13 @@ class Ledger:
         if qty > self._stock.get(sku, 0):
             raise ValueError("qty to remove exceeds stock")
         self._stock[sku] -= qty
+        self._history.append(("remove", sku, qty))

     def quantity(self, sku):
         return self._stock.get(sku, 0)

     def skus(self):
         return sorted(self._stock)
+
+    def history(self):
+        return list(self._history)

